async def act(page):
    """
    From the current Create Product Settings screen, dismiss the popup, click Continue
    (using the full table->row->button path), fill a simple product named
    "Energy-Bulk Women Shirt" priced $60 with SKU ENERGY-BULK-W-S, set Qty=50
    and mark In Stock, choose Size = S and Color = Blue, then click Save.
    """

    # Helper utilities
    async def click_if_exists(locator):
        try:
            if await locator.count() > 0:
                await locator.click()
                return True
        except Exception:
            return False
        return False

    async def fill_textbox_by_names(value, *names):
        for n in names:
            try:
                tb = page.get_by_role("textbox", name=n)
                if await tb.count() > 0:
                    await tb.fill(value)
                    return True
            except Exception:
                continue
        return False

    async def select_combobox_by_labels(locator, *labels):
        for lbl in labels:
            try:
                await locator.select_option(label=lbl)
                return True
            except Exception:
                try:
                    await locator.select_option(value=lbl)
                    return True
                except Exception:
                    continue
        return False

    # 0) Dismiss any blocking popup if present. Try common close names and scan aria-labels.
    for name in ("Close", "close", "Dismiss", "dismiss", "×", "X"):
        try:
            btn = page.get_by_role("button", name=name)
            if await btn.count() > 0:
                await btn.click()
                await page.wait_for_timeout(300)
                break
        except Exception:
            pass

    try:
        all_buttons = page.get_by_role("button")
        for i in range(await all_buttons.count()):
            b = all_buttons.nth(i)
            try:
                aria = await b.get_attribute("aria-label")
                if aria and "close" in aria.lower():
                    await b.click()
                    await page.wait_for_timeout(300)
                    break
            except Exception:
                continue
    except Exception:
        pass

    # 1) Click Continue using full element-scoped path: table -> row "Continue" -> button "Continue"
    try:
        table = page.get_by_role("table")
        row = table.get_by_role("row", name="Continue")
        continue_btn = row.get_by_role("button", name="Continue")
        if await continue_btn.count() > 0:
            await continue_btn.click()
            try:
                await page.wait_for_load_state("networkidle", timeout=10000)
            except Exception:
                await page.wait_for_timeout(1200)
        else:
            # fallback to any Continue button
            cb = page.get_by_role("button", name="Continue")
            if await cb.count() > 0:
                await cb.click()
                try:
                    await page.wait_for_load_state("networkidle", timeout=10000)
                except Exception:
                    await page.wait_for_timeout(1200)
    except Exception:
        # if we can't proceed to the form, stop here
        return

    # small pause to let the product form become interactive
    await page.wait_for_timeout(500)

    # 2) Fill Product Name, SKU, Price (try common accessible names)
    await fill_textbox_by_names("Energy-Bulk Women Shirt", "Name", "Product Name", "name")
    await fill_textbox_by_names("ENERGY-BULK-W-S", "SKU", "sku")
    await fill_textbox_by_names("60", "Price", "price")

    # 3) Open Inventory tab if present and set Qty = 50
    try:
        inv_tab = page.get_by_role("tab", name="Inventory")
        if await inv_tab.count() > 0:
            await inv_tab.click()
            await page.wait_for_timeout(300)
    except Exception:
        try:
            stock_tab = page.get_by_role("tab", name="Stock")
            if await stock_tab.count() > 0:
                await stock_tab.click()
                await page.wait_for_timeout(300)
        except Exception:
            pass

    await fill_textbox_by_names("50", "Qty", "Quantity", "qty", "Quantity In Stock")

    # Mark In Stock using combobox select_option (iterate comboboxes until success)
    try:
        combs = page.get_by_role("combobox")
        for i in range(await combs.count()):
            cb = combs.nth(i)
            if await select_combobox_by_labels(cb, "In Stock", "Yes", "1"):
                break
    except Exception:
        pass

    # 4) Select Size = S and Color = Blue
    try:
        size_cb = page.get_by_role("combobox", name="Size")
        if await size_cb.count() > 0:
            await select_combobox_by_labels(size_cb, "S", "Small")
        else:
            combs = page.get_by_role("combobox")
            for i in range(await combs.count()):
                cb = combs.nth(i)
                if await select_combobox_by_labels(cb, "S", "Small"):
                    break
    except Exception:
        pass

    try:
        color_cb = page.get_by_role("combobox", name="Color")
        if await color_cb.count() > 0:
            await select_combobox_by_labels(color_cb, "Blue", "blue")
        else:
            combs = page.get_by_role("combobox")
            for i in range(await combs.count()):
                cb = combs.nth(i)
                if await select_combobox_by_labels(cb, "Blue", "blue"):
                    break
    except Exception:
        pass

    await page.wait_for_timeout(400)

    # 5) Click Save (final action; may navigate away)
    try:
        save_btn = page.get_by_role("button", name="Save")
        if await save_btn.count() > 0:
            await save_btn.click()
            try:
                await page.wait_for_load_state("networkidle", timeout=10000)
            except Exception:
                await page.wait_for_timeout(2000)
        else:
            groups = page.get_by_role("group")
            for i in range(await groups.count()):
                g = groups.nth(i)
                btn = g.get_by_role("button", name="Save")
                if await btn.count() > 0:
                    await btn.click()
                    try:
                        await page.wait_for_load_state("networkidle", timeout=10000)
                    except Exception:
                        await page.wait_for_timeout(2000)
                    break
    except Exception:
        pass

